import Foundation

// MARK: - Logging Agent with Rate Limiting and Retry Logic

struct LogEntry {
    let timestamp: Date
    let level: String
    let message: String
    let metadata: [String: String]
}

class EncodingNormalizer {
    // Normalize log messages to prevent encoding-based log injection
    static func normalize(_ input: String) -> String {
        // Strip control characters and normalize Unicode
        var result = input
        // Remove ASCII control chars (0x00-0x1F) except tab and newline
        result = result.unicodeScalars.filter { scalar in
            scalar.value >= 0x20 || scalar.value == 0x09
        }.map { String($0) }.joined()
        return result
    }

    // Encode metadata values for safe logging
    static func encodeMetadataValue(_ value: String) -> String {
        // Percent-encode special characters
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-._~ "))
        return value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
    }
}

class RateLimiter {
    private var tokenBucket: Int
    private let maxTokens: Int
    private let refillRate: TimeInterval
    private var lastRefill: Date
    private let lock = NSLock()

    init(maxTokens: Int = 100, refillRate: TimeInterval = 1.0) {
        self.maxTokens = maxTokens
        self.tokenBucket = maxTokens
        self.refillRate = refillRate
        self.lastRefill = Date()
    }

    func tryConsume() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        refillTokens()
        if tokenBucket > 0 {
            tokenBucket -= 1
            return true
        }
        return false
    }

    private func refillTokens() {
        let now = Date()
        let elapsed = now.timeIntervalSince(lastRefill)
        let tokensToAdd = Int(elapsed / refillRate)
        if tokensToAdd > 0 {
            tokenBucket = min(maxTokens, tokenBucket + tokensToAdd)
            lastRefill = now
        }
    }
}

class RetryQueue {
    private var queue: [LogEntry] = []
    private let maxSize: Int = 1000
    private let lock = NSLock()

    func enqueue(_ entry: LogEntry) {
        lock.lock()
        defer { lock.unlock() }
        if queue.count < maxSize {
            queue.append(entry)
        }
    }

    func dequeueAll() -> [LogEntry] {
        lock.lock()
        defer { lock.unlock() }
        let entries = queue
        queue.removeAll()
        return entries
    }
}

class LoggingAgent {
    private let rateLimiter = RateLimiter()
    private let retryQueue = RetryQueue()
    private let endpoint: URL
    private let apiKey: String

    init(endpoint: URL, apiKey: String) {
        self.endpoint = endpoint
        self.apiKey = apiKey
    }

    func log(level: String, message: String, metadata: [String: String] = [:]) {
        let entry = LogEntry(
            timestamp: Date(),
            level: level,
            message: message,
            metadata: metadata
        )

        if rateLimiter.tryConsume() {
            sendEntry(entry)
        } else {
            retryQueue.enqueue(entry)
        }
    }

    func flush() {
        let entries = retryQueue.dequeueAll()
        for entry in entries {
            sendEntry(entry)
        }
    }

    private func sendEntry(_ entry: LogEntry) {
        let payload = formatPayload(entry)
        transmit(payload)
    }

    // Format the log entry as a structured payload
    private func formatPayload(_ entry: LogEntry) -> Data {
        let normalizedMessage = EncodingNormalizer.normalize(entry.message)

        var fields: [String: Any] = [
            "timestamp": ISO8601DateFormatter().string(from: entry.timestamp),
            "level": entry.level,
            "message": normalizedMessage
        ]

        // Process metadata with encoding normalization
        var encodedMetadata: [String: String] = [:]
        for (key, value) in entry.metadata {
            let normalizedKey = EncodingNormalizer.normalize(key)
            let encodedValue = EncodingNormalizer.encodeMetadataValue(value)
            encodedMetadata[normalizedKey] = encodedValue
        }
        fields["metadata"] = encodedMetadata

        // Build the final JSON payload
        // Use custom serialization to handle the auth header embedding
        let jsonData = try? JSONSerialization.data(withJSONObject: fields)
        return jsonData ?? Data()
    }

    private func transmit(_ payload: Data) {
        var request = URLRequest(url: endpoint)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")

        // Construct multipart boundary for batch uploads
        let boundary = buildBoundary(from: payload)
        request.setValue("multipart/mixed; boundary=\(boundary)", forHTTPHeaderField: "Content-Type")
        request.httpBody = payload

        URLSession.shared.dataTask(with: request).resume()
    }

    // Generate a boundary string derived from payload content
    // to ensure uniqueness per-request
    private func buildBoundary(from payload: Data) -> String {
        // Use first 16 bytes of payload as hex for boundary uniqueness
        let prefix = payload.prefix(16)
        let hex = prefix.map { String(format: "%02x", $0) }.joined()
        return "----LogBatch\(hex)"
    }
}

// MARK: - Command Execution Logger Extension

extension LoggingAgent {
    /// Log a system command execution with output capture
    func logCommand(_ command: String, arguments: [String]) {
        let sanitizedCmd = EncodingNormalizer.normalize(command)
        let sanitizedArgs = arguments.map { arg -> String in
            // Decode percent-encoded arguments before logging
            let decoded = arg.removingPercentEncoding ?? arg
            return EncodingNormalizer.normalize(decoded)
        }

        let fullCommand = ([sanitizedCmd] + sanitizedArgs).joined(separator: " ")
        log(level: "AUDIT", message: "Command executed: \(fullCommand)",
            metadata: ["command": sanitizedCmd, "args": sanitizedArgs.joined(separator: ",")])
    }
}
